1	// 包厢状态同步核心领域逻辑：有限状态机 + 交接事件 + 乐观锁 + SLA 预警
2	import fs from 'node:fs';
3	import path from 'node:path';
4	
5	export const STATE = {
6	  IN_USE: 'IN_USE',       // 使用中
7	  TO_CLEAN: 'TO_CLEAN',   // 待清洁
8	  CLEANING: 'CLEANING',   // 清洁中
9	  INSPECTING: 'INSPECTING', // 检查中
10	  OPEN: 'OPEN',           // 可开放
11	};
12	
13	export const STATE_LABEL = {
14	  IN_USE: '使用中',
15	  TO_CLEAN: '待清洁',
16	  CLEANING: '清洁中',
17	  INSPECTING: '检查中',
18	  OPEN: '可开放',
19	};
20	
21	export const ACTION = {
22	  CHECK_IN: 'CHECK_IN',
23	  CHECK_OUT: 'CHECK_OUT',
24	  CLAIM: 'CLAIM',
25	  RELEASE_CLAIM: 'RELEASE_CLAIM',
26	  SUBMIT_CLEAN: 'SUBMIT_CLEAN',
27	  PASS_INSPECTION: 'PASS_INSPECTION',
28	  REJECT_INSPECTION: 'REJECT_INSPECTION',
29	  ROLLBACK: 'ROLLBACK',
30	};
31	
32	export const ACTION_LABEL = {
33	  CHECK_IN: '开房',
34	  CHECK_OUT: '退房',
35	  CLAIM: '接单清洁',
36	  RELEASE_CLAIM: '放弃接单',
37	  SUBMIT_CLEAN: '清洁报检',
38	  PASS_INSPECTION: '检查通过',
39	  REJECT_INSPECTION: '检查不通过',
40	  ROLLBACK: '异常退回',
41	};
42	
43	export const ROLE = {
44	  FRONT: 'FRONT',     // 前台
45	  CLEANER: 'CLEANER', // 保洁
46	  MANAGER: 'MANAGER', // 值班经理
47	};
48	
49	export const ROLE_LABEL = { FRONT: '前台', CLEANER: '保洁', MANAGER: '值班经理' };
50	
51	// 各动作允许的角色
52	const ACTION_ROLES = {
53	  CHECK_IN: [ROLE.FRONT],
54	  CHECK_OUT: [ROLE.FRONT],
55	  CLAIM: [ROLE.CLEANER],
56	  RELEASE_CLAIM: [ROLE.CLEANER, ROLE.MANAGER],
57	  SUBMIT_CLEAN: [ROLE.CLEANER],
58	  PASS_INSPECTION: [ROLE.MANAGER],
59	  REJECT_INSPECTION: [ROLE.MANAGER],
60	  ROLLBACK: [ROLE.MANAGER],
61	};
62	
63	// 正常流转：动作 -> [起始状态, 目标状态]
64	const FLOW = {
65	  CHECK_IN: [STATE.OPEN, STATE.IN_USE],
66	  CHECK_OUT: [STATE.IN_USE, STATE.TO_CLEAN],
67	  CLAIM: [STATE.TO_CLEAN, STATE.CLEANING],
68	  RELEASE_CLAIM: [STATE.CLEANING, STATE.TO_CLEAN],
69	  SUBMIT_CLEAN: [STATE.CLEANING, STATE.INSPECTING],
70	  PASS_INSPECTION: [STATE.INSPECTING, STATE.OPEN],
71	  REJECT_INSPECTION: [STATE.INSPECTING, STATE.CLEANING],
72	};
73	
74	// 需要强制填写原因的动作
75	const REASON_REQUIRED = new Set([ACTION.REJECT_INSPECTION, ACTION.ROLLBACK]);
76	
77	// 每个状态当前阶段的责任人由事件上的哪些字段承载
78	function responsibleFor(ev) {
79	  if (!ev) return null;
80	  return { userId: ev.toResponsibleId, name: ev.toResponsible };
81	}
82	
83	export class DomainError extends Error {
84	  constructor(message, status = 400, code = 'DOMAIN_ERROR') {
85	    super(message);
86	    this.status = status;
87	    this.code = code;
88	  }
89	}
90	
91	function slaFromEnv() {
92	  const num = (v, d) => {
93	    const n = Number(v);
94	    return Number.isFinite(n) && n > 0 ? n : d;
95	  };
96	  return {
97	    [STATE.TO_CLEAN]: num(process.env.SLA_CLAIM_SECONDS, 120),
98	    [STATE.CLEANING]: num(process.env.SLA_CLEAN_SECONDS, 300),
99	    [STATE.INSPECTING]: num(process.env.SLA_INSPECT_SECONDS, 180),
100	  };
101	}
102	
103	// ---- 纯函数：计算动作目标状态（ROLLBACK 依赖历史） ----
104	export function nextState(action, currentState, events) {
105	  if (action === ACTION.ROLLBACK) {
106	    // 找到最近一次非 ROLLBACK 的流转，退回到它之前的状态
107	    for (let i = events.length - 1; i >= 0; i--) {
108	      if (events[i].action !== ACTION.ROLLBACK) {
109	        const prev = events[i].fromState;
110	        if (!prev) throw new DomainError('该包厢初始即此状态，无可退回的上一步');
111	        // 不允许借退回跨越关键业务节点
112	        if (prev === STATE.OPEN && currentState !== STATE.INSPECTING) {
113	          throw new DomainError('已开放包厢只能在检查环节退回，不允许跨节点退回');
114	        }
115	        return prev;
116	      }
117	    }
118	    throw new DomainError('该包厢初始即此状态，无可退回的上一步');
119	  }
120	  const [from, to] = FLOW[action];
121	  if (!from) throw new DomainError(`未知动作: ${action}`);
122	  if (currentState !== from) {
123	    throw new DomainError(`当前状态「${STATE_LABEL[currentState]}」不允许执行「${ACTION_LABEL[action]}」`);
124	  }
125	  return to;
126	}
127	
128	// 每个状态可执行的动作（供前端按角色渲染按钮）
129	export function allowedActions(state, role) {
130	  const result = [];
131	  for (const action of Object.keys(FLOW)) {
132	    if (FLOW[action][0] === state && ACTION_ROLES[action].includes(role)) result.push(action);
133	  }
134	  if (role === ROLE.MANAGER) result.push(ACTION.ROLLBACK);
135	  return result;
136	}
137	
138	export class RoomStore {
139	  constructor({ dir = './data', now = () => Date.now() } = {}) {
140	    this.dir = dir;
141	    this.now = now;
142	    this.sla = slaFromEnv();
143	    fs.mkdirSync(dir, { recursive: true });
144	    this.rooms = new Map();       // id -> room
145	    this.events = new Map();      // id -> event[]
146	    this.idempotency = new Map(); // key -> {roomId, event}
147	    this.locks = new Map();       // roomId -> Promise 链（串行化同包厢写入）
148	    this.alerts = new Map();      // `${roomId}:${state}` -> alert
149	    this.listeners = new Set();
150	    this._load();
151	  }
152	
153	  _file() {
154	    return path.join(this.dir, 'events-db.json');
155	  }
156	
157	  _load() {
158	    const f = this._file();
159	    if (!fs.existsSync(f)) return;
160	    try {
161	      const data = JSON.parse(fs.readFileSync(f, 'utf8'));
162	      for (const r of data.rooms || []) {
163	        this.rooms.set(r.id, { ...r });
164	        this.events.set(r.id, []);
165	      }
166	      for (const ev of data.events || []) {
167	        this.events.get(ev.roomId)?.push(ev);
168	      }
169	      for (const [id] of this.rooms) this._rebuildRoomFromEvents(id, { touch: false });
170	      for (const [k, v] of Object.entries(data.alerts || {})) this.alerts.set(k, { ...v });
171	    } catch (e) {
172	      console.error('加载数据失败，使用空数据启动:', e.message);
173	    }
174	  }
175	
176	  _persist() {
177	    const data = {
178	      rooms: [...this.rooms.values()].map(({ id, name }) => ({ id, name })),
179	      events: [...this.events.values()].flat(),
180	      alerts: Object.fromEntries(this.alerts),
181	    };
182	    const tmp = this._file() + '.tmp';
183	    fs.writeFileSync(tmp, JSON.stringify(data));
184	    fs.renameSync(tmp, this._file());
185	  }
186	
187	  seedIfEmpty(rooms) {
188	    if (this.rooms.size > 0) return;
189	    for (const r of rooms) {
190	      this.rooms.set(r.id, { id: r.id, name: r.name });
191	      this.events.set(r.id, []);
192	    }
193	    for (const r of rooms) {
194	      const [action, fromState, toState, offsetSec, operatorName] = r.seed;
195	      const t = this.now() - offsetSec * 1000;
196	      let operatorRole = ROLE.FRONT;
197	      if (action === ACTION.CLAIM) operatorRole = ROLE.CLEANER;
198	      if (action === ACTION.SUBMIT_CLEAN) operatorRole = ROLE.CLEANER;
199	      let toResponsible = operatorName;
200	      let toResponsibleId = `seed-${r.id}`;
201	      if (action === ACTION.SUBMIT_CLEAN) {
202	        toResponsible = '值班经理';
203	        toResponsibleId = 'manager-on-duty';
204	      }
205	      this.events.get(r.id).push({
206	        id: `${r.id}-seed`,
207	        roomId: r.id,
208	        action,
209	        fromState,
210	        toState,
211	        operatorId: `seed-${r.id}`,
212	        operatorName,
213	        operatorRole,
214	        toResponsibleId,
215	        toResponsible,
216	        reason: null,
217	        idempotencyKey: null,
218	        at: new Date(t).toISOString(),
219	        version: 1,
220	      });
221	    }
222	    for (const [id] of this.rooms) this._rebuildRoomFromEvents(id, { touch: false });
223	    this._persist();
224	  }
225	
226	  _rebuildRoomFromEvents(roomId, { touch = true } = {}) {
227	    const evs = this.events.get(roomId) || [];
228	    const room = this.rooms.get(roomId);
229	    if (!room) return;
230	    const last = evs[evs.length - 1];
231	    if (!last) {
232	      room.state = STATE.OPEN;
233	      room.version = 0;
234	      room.responsible = null;
235	    } else {
236	      room.state = last.toState;
237	      room.version = last.version;
238	      room.responsible = responsibleFor(last);
239	      room.updatedBy = last.operatorName;
240	    }
241	    room.since = last ? last.at : null;
242	    if (touch) room.updatedAt = new Date(this.now()).toISOString();
243	    else room.updatedAt = last ? last.at : null;
244	  }
245	
246	  subscribe(fn) {
247	    this.listeners.add(fn);
248	    return () => this.listeners.delete(fn);
249	  }
250	
251	  _emit(type, payload) {
252	    for (const fn of this.listeners) {
253	      try { fn(type, payload); } catch (e) { console.error('listener error', e); }
254	    }
255	  }
256	
257	  // 同包厢写入串行化，消除读-改-写竞态
258	  async _withLock(roomId, fn) {
259	    const prev = this.locks.get(roomId) || Promise.resolve();
260	    let release;
261	    const next = new Promise((res) => { release = res; });
262	    this.locks.set(roomId, prev.then(() => next));
263	    await prev.catch(() => {});
264	    try {
265	      return await fn();
266	    } finally {
267	      release();
268	      if (this.locks.get(roomId) === next) this.locks.delete(roomId);
269	    }
270	  }
271	
272	  snapshot() {
273	    return {
274	      now: new Date(this.now()).toISOString(),
275	      sla: this.sla,
276	      rooms: [...this.rooms.values()].map((r) => ({ ...r })),
277	      alerts: [...this.alerts.values()],
278	    };
279	  }
280	
281	  history(roomId, limit = 50) {
282	    const room = this.rooms.get(roomId);
283	    if (!room) throw new DomainError('包厢不存在', 404, 'NOT_FOUND');
284	    const evs = this.events.get(roomId) || [];
285	    return evs.slice(-limit).reverse();
286	  }
287	
288	  /**
289	   * 执行一次状态流转
290	   * @param {string} roomId
291	   * @param {object} op {action, expectedVersion, reason, idempotencyKey}
292	   * @param {object} operator {id, name, role}
293	   */
294	  async commitTransition(roomId, op, operator) {
295	    return this._withLock(roomId, () => this._commitLocked(roomId, op, operator));
296	  }
297	
298	  _commitLocked(roomId, op, operator) {
299	    const room = this.rooms.get(roomId);
300	    if (!room) throw new DomainError('包厢不存在', 404, 'NOT_FOUND');
301	    const { action, expectedVersion, reason = null } = op;
302	    const idemKey = op.idempotencyKey || null;
303	
304	    // 幂等：相同 key 直接返回首次结果
305	    if (idemKey) {
306	      const cached = this.idempotency.get(idemKey);
307	      if (cached && cached.roomId === roomId) {
308	        return { event: cached.event, duplicated: true };
309	      }
310	    }
311	
312	    if (!operator?.id || !operator?.name || !ROLE[operator.role]) {
313	      throw new DomainError('操作人信息不完整', 401, 'UNAUTHORIZED');
314	    }
315	    if (!ACTION[action]) throw new DomainError(`未知动作: ${action}`);
316	    if (!ACTION_ROLES[action].includes(operator.role)) {
317	      throw new DomainError(`${ROLE_LABEL[operator.role]}无权执行「${ACTION_LABEL[action]}」`, 403, 'FORBIDDEN');
318	    }
319	    if (typeof expectedVersion !== 'number') {
320	      throw new DomainError('缺少 expectedVersion', 409, 'VERSION_CONFLICT');
321	    }
322	    if (expectedVersion !== room.version) {
323	      throw new DomainError(
324	        `状态已被其他人更新（你基于 v${expectedVersion}，当前 v${room.version}），请刷新后重试`,
325	        409, 'VERSION_CONFLICT',
326	      );
327	    }
328	    if (REASON_REQUIRED.has(action) && (!reason || !String(reason).trim())) {
329	      throw new DomainError(`「${ACTION_LABEL[action]}」必须填写原因`);
330	    }
331	    // 保洁只能放弃自己的接单（值班经理可强制收回）
332	    if (action === ACTION.RELEASE_CLAIM && operator.role === ROLE.CLEANER) {
333	      const claim = [...(this.events.get(roomId) || [])].reverse()
334	        .find((e) => e.action === ACTION.CLAIM);
335	      if (claim && claim.operatorId !== operator.id) {
336	        throw new DomainError('只能放弃自己接的清洁单', 403, 'FORBIDDEN');
337	      }
338	    }
339	
340	    const evs = this.events.get(roomId);
341	    const fromState = room.state;
342	    const toState = nextState(action, fromState, evs);
343	
344	    let toResponsible = operator.name;
345	    let toResponsibleId = operator.id;
346	    if (action === ACTION.CHECK_OUT) {
347	      // 待清洁阶段：等待保洁接单，责任暂挂前台
348	      toResponsible = operator.name;
349	    } else if (action === ACTION.SUBMIT_CLEAN) {
350	      toResponsible = '值班经理'; // 检查责任人角色，具体经理检查时确定
351	      toResponsibleId = 'manager-on-duty';
352	    } else if (action === ACTION.REJECT_INSPECTION) {
353	      // 退回原保洁返工：取历史上最近一次接单的保洁
354	      let claim = null;
355	      for (const e of evs) if (e.action === ACTION.CLAIM) claim = e;
356	      toResponsible = claim ? claim.operatorName : '原保洁';
357	      toResponsibleId = claim ? claim.operatorId : null;
358	    } else if (action === ACTION.ROLLBACK) {
359	      // 恢复为目标状态当时的责任人：找到建立该状态的事件
360	      const anchor = [...evs].reverse().find((e) => e.action !== ACTION.ROLLBACK);
361	      const established = [...evs].reverse().find((e) => e.toState === toState && e.action !== ACTION.ROLLBACK);
362	      toResponsible = established?.toResponsible || anchor?.toResponsible || operator.name;
363	      toResponsibleId = established?.toResponsibleId || operator.id;
364	    }
365	
366	    const event = {
367	      id: `ev-${roomId}-${room.version + 1}-${this.now().toString(36)}`,
368	      roomId,
369	      action,
370	      fromState,
371	      toState,
372	      operatorId: operator.id,
373	      operatorName: operator.name,
374	      operatorRole: operator.role,
375	      toResponsibleId,
376	      toResponsible,
377	      reason: reason ? String(reason).trim() : null,
378	      idempotencyKey: idemKey,
379	      at: new Date(this.now()).toISOString(),
380	      version: room.version + 1,
381	    };
382	    evs.push(event);
383	    this._rebuildRoomFromEvents(roomId);
384	    if (idemKey) this.idempotency.set(idemKey, { roomId, event });
385	
386	    // 流转后清除本包厢旧预警（tick 会按新状态重新评估）
387	    for (const key of [...this.alerts.keys()]) {
388	      if (key.startsWith(`${roomId}:`)) this.alerts.delete(key);
389	    }
390	
391	    this._persist();
392	    this._emit('transition', { event, room: { ...room } });
393	    this._evaluateAlerts(true);
394	    return { event, duplicated: false };
395	  }
396	
397	  _alertKey(roomId, state) {
398	    return `${roomId}:${state}`;
399	  }
400	
401	  // 返回本轮产生/升级/消除的变化，供广播
402	  tickAlerts() {
403	    return this._evaluateAlerts(false);
404	  }
405	
406	  _evaluateAlerts(transitionJustHappened) {
407	    const changes = [];
408	    const activeKeys = new Set();
409	    for (const room of this.rooms.values()) {
410	      const limit = this.sla[room.state];
411	      if (!limit || !room.since) continue;
412	      const key = this._alertKey(room.id, room.state);
413	      activeKeys.add(key);
414	      const elapsed = (this.now() - new Date(room.since).getTime()) / 1000;
415	      if (elapsed < limit) continue;
416	
417	      const existing = this.alerts.get(key);
418	      const overdueSec = Math.round(elapsed - limit);
419	      if (!existing) {
420	        const alert = {
421	          key,
422	          roomId: room.id,
423	          roomName: room.name,
424	          state: room.state,
425	          level: elapsed >= limit * 2 ? 'CRITICAL' : 'WARNING',
426	          limitSec: limit,
427	          overdueSec,
428	          responsible: room.responsible,
429	          since: room.since,
430	          raisedAt: new Date(this.now()).toISOString(),
431	        };
432	        this.alerts.set(key, alert);
433	        changes.push({ type: 'raised', alert });
434	      } else {
435	        const level = elapsed >= limit * 2 ? 'CRITICAL' : 'WARNING';
436	        if (level !== existing.level || overdueSec !== existing.overdueSec) {
437	          const updated = { ...existing, level, overdueSec, responsible: room.responsible };
438	          this.alerts.set(key, updated);
439	          if (level !== existing.level) changes.push({ type: 'escalated', alert: updated });
440	        }
441	      }
442	    }
443	    // 状态已变化/已恢复的预警自动消除
444	    for (const key of [...this.alerts.keys()]) {
445	      if (!activeKeys.has(key)) {
446	        const alert = this.alerts.get(key);
447	        this.alerts.delete(key);
448	        changes.push({ type: 'resolved', alert });
449	      }
450	    }
451	    if (changes.length) this._emit('alerts', { changes, snapshot: this.snapshot().alerts });
452	    return changes;
453	  }
454	}
