177	<script>
178	const ACTIONS_NEED_REASON = new Set(['REJECT_INSPECTION', 'ROLLBACK']);
179	const ACTION_BTN_CLASS = {
180	  CHECK_IN: 'primary', PASS_INSPECTION: 'primary',
181	  REJECT_INSPECTION: 'danger', ROLLBACK: 'danger',
182	};
183	
184	let state = null;
185	const feedItems = [];
186	
187	// ---- 身份（演示：直接由前端设置；生产由服务端会话解析）----
188	const PRESET_NAME = { FRONT: '前台-小林', CLEANER: '保洁-王姐', MANAGER: '值班经理-老赵' };
189	const roleEl = document.getElementById('role');
190	const nameEl = document.getElementById('userName');
191	roleEl.value = localStorage.getItem('role') || 'FRONT';
192	nameEl.value = localStorage.getItem('userName') || PRESET_NAME[roleEl.value];
193	roleEl.onchange = () => { nameEl.value = PRESET_NAME[roleEl.value]; saveIdentity(); render(); };
194	nameEl.onchange = saveIdentity;
195	function saveIdentity() {
196	  localStorage.setItem('role', roleEl.value);
197	  localStorage.setItem('userName', nameEl.value.trim() || PRESET_NAME[roleEl.value]);
198	}
199	function operator() {
200	  const role = roleEl.value;
201	  const name = nameEl.value.trim() || PRESET_NAME[role];
202	  return { 'X-Role': role, 'X-User-Name': name, 'X-User-Id': `${role}:${name}` };
203	}
204	
205	// ---- 拉取 / 推送 ----
206	async function fetchSnapshot() {
207	  const res = await fetch('/api/rooms');
208	  state = await res.json();
209	  render();
210	}
211	
212	function connectSSE() {
213	  const es = new EventSource('/api/events');
214	  es.addEventListener('hello', (e) => { state = JSON.parse(e.data); setConn(true); render(); });
215	  es.addEventListener('transition', (e) => {
216	    const { event, room } = JSON.parse(e.data);
217	    feedItems.unshift(event);
218	    if (feedItems.length > 100) feedItems.pop();
219	    fetchSnapshot();
220	    if (event.operatorId !== operator()['X-User-Id']) {
221	      toast(`「${room.name}」被 ${event.operatorName} 更新：${stateLabel(event.toState)}`, 'ok');
222	    }
223	  });
224	  es.addEventListener('alerts', () => fetchSnapshot());
225	  es.onopen = () => setConn(true);
226	  es.onerror = () => { setConn(false); setTimeout(() => { es.close(); connectSSE(); }, 3000); };
227	}
228	function setConn(ok) {
229	  document.getElementById('connDot').classList.toggle('off', !ok);
230	  document.getElementById('connText').textContent = ok ? '实时连接中' : '连接断开，重连中…';
231	}
