233	// ---- 渲染 ----
234	function fmtClock(iso) {
235	  const d = new Date(iso);
236	  return d.toLocaleTimeString('zh-CN', { hour12: false });
237	}
238	function elapsed(iso) {
239	  return Math.max(0, (Date.now() - new Date(iso).getTime()) / 1000);
240	}
241	function fmtDur(sec) {
242	  sec = Math.floor(sec);
243	  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
244	  return h ? `${h}h${m}m` : m ? `${m}m${s}s` : `${s}s`;
245	}
246	function roomAlert(roomId) {
247	  return (state?.alerts || []).find(a => a.roomId === roomId);
248	}
249	function timerClass(room, al) {
250	  if (!state.sla[room.state] || !room.since) return '';
251	  if (al) return al.level === 'CRITICAL' ? 'critical' : 'overdue';
252	  const e = elapsed(room.since);
253	  if (e >= state.sla[room.state] * 2) return 'critical';
254	  if (e >= state.sla[room.state]) return 'overdue';
255	  return '';
256	}
257	
258	function render() {
259	  if (!state) return;
260	  renderAlerts();
261	  const grid = document.getElementById('grid');
262	  const role = roleEl.value;
263	  grid.innerHTML = '';
264	  for (const room of state.rooms) {
265	    const al = roomAlert(room.id);
266	    const card = document.createElement('div');
267	    card.className = `card s-${room.state}${al ? ' has-alert' : ''}`;
268	    const actions = room.allowedByRole[role] || [];
269	    const sla = state.sla[room.state];
270	    card.innerHTML = `
271	      <h3>${room.name}
272	        <span class="badge b-${room.state}">${room.stateLabel}</span>
273	        <span style="margin-left:auto;font-size:11px;color:var(--muted)">v${room.version}</span>
274	      </h3>
275	      <div class="meta">
276	        <span>当前责任人：<b>${room.responsible?.name || '—'}</b></span>
277	        <span>进入状态：${room.since ? fmtClock(room.since) : '—'}</span>
278	        <span>停留：<span class="timer ${timerClass(room, al)}" data-since="${room.since || ''}" data-sla="${sla || ''}">
279	          ${room.since ? fmtDur(elapsed(room.since)) : ''}
280	        </span>${sla ? `（时限 ${fmtDur(sla)}）` : ''}</span>
281	      </div>
282	      <div class="actions">
283	        ${actions.map(a => `<button class="${ACTION_BTN_CLASS[a] || ''}" data-action="${a}">${actionLabel(a)}</button>`).join('')}
284	        <button class="ghost" data-history>交接记录</button>
285	      </div>`;
286	    card.querySelectorAll('[data-action]').forEach(btn => {
287	      btn.onclick = () => doAction(room, btn.dataset.action);
288	    });
289	    card.querySelector('[data-history]').onclick = () => showHistory(room);
290	    grid.appendChild(card);
291	  }
292	  renderFeed();
293	}
