295	function actionLabel(a) {
296	  return {
297	    CHECK_IN: '开房', CHECK_OUT: '退房', CLAIM: '接单清洁', RELEASE_CLAIM: '放弃接单',
298	    SUBMIT_CLEAN: '清洁报检', PASS_INSPECTION: '检查通过', REJECT_INSPECTION: '检查不通过',
299	    ROLLBACK: '异常退回',
300	  }[a];
301	}
302	
303	function renderAlerts() {
304	  const box = document.getElementById('alerts');
305	  const alerts = (state.alerts || []).slice().sort((a, b) =>
306	    (a.level === 'CRITICAL' ? 0 : 1) - (b.level === 'CRITICAL' ? 0 : 1));
307	  if (!alerts.length) { box.innerHTML = ''; return; }
308	  box.innerHTML = alerts.map(a => `
309	    <div class="alert ${a.level === 'CRITICAL' ? 'critical' : ''}">
310	      <span class="tag">${a.level === 'CRITICAL' ? '⛔ 严重超时' : '⚠️ 超时提醒'}</span>
311	      <span><b>${a.roomName}</b> ${stateLabel(a.state)} 已超时 <b>${fmtDur(a.overdueSec)}</b>
312	        （时限 ${fmtDur(a.limitSec)}），责任人：${a.responsible?.name || '—'}</span>
313	      <span class="time">${fmtClock(a.raisedAt)} 触发</span>
314	    </div>`).join('');
315	}
316	function stateLabel(s) {
317	  return { IN_USE: '使用中', TO_CLEAN: '待清洁', CLEANING: '清洁中', INSPECTING: '检查中', OPEN: '可开放' }[s];
318	}
