320	function renderFeed() {
321	  const box = document.getElementById('feed');
322	  if (!feedItems.length) { box.innerHTML = '<div style="color:var(--muted);font-size:12.5px">暂无动态，操作后将在此显示</div>'; return; }
323	  box.innerHTML = feedItems.slice(0, 30).map(ev => `
324	    <div class="item">
325	      <div class="row1">
326	        <span class="who">${ev.operatorName}（${roleLabel(ev.operatorRole)}）→ ${ev.toResponsible}</span>
327	        <span class="t">${fmtClock(ev.at)}</span>
328	      </div>
329	      <div class="row2">
330	        ${roomName(ev.roomId)} · ${actionLabel(ev.action)}
331	        ${ev.fromState ? `${stateLabel(ev.fromState)} → ` : ''}${stateLabel(ev.toState)}
332	        ${ev.reason ? ` · <span class="reason">原因：${escapeHtml(ev.reason)}</span>` : ''}
333	        ${ev.idempotencyKey && ev.idempotencyKey.startsWith('idem-retry') ? ' · 重试命中' : ''}
334	      </div>
335	    </div>`).join('');
336	}
337	function roleLabel(r) { return { FRONT: '前台', CLEANER: '保洁', MANAGER: '值班经理' }[r] || r; }
338	function roomName(id) { return state?.rooms?.find(r => r.id === id)?.name || id; }
339	function escapeHtml(s) { return s.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
340	
341	// ---- 操作 ----
342	let pending = null;
343	function doAction(room, action) {
344	  const exec = (reason) => postTransition(room, action, reason);
345	  if (ACTIONS_NEED_REASON.has(action)) {
346	    pending = { room, action };
347	    document.getElementById('reasonTitle').textContent =
348	      `${actionLabel(action)}：${room.name}（v${room.version} → v${room.version + 1}）`;
349	    document.getElementById('reasonHint').textContent =
350	      action === 'ROLLBACK'
351	        ? `当前「${room.stateLabel}」将退回到上一状态，并恢复原责任人。该操作仅值班经理可用，会永久留痕。`
352	        : '检查不通过将退回原保洁返工，请说明不通过原因。';
353	    document.getElementById('reasonInput').value = '';
354	    document.getElementById('reasonModal').classList.add('show');
355	    document.getElementById('reasonInput').focus();
356	  } else {
357	    exec(null);
358	  }
359	}
360	document.getElementById('reasonConfirm').onclick = async () => {
361	  const reason = document.getElementById('reasonInput').value.trim();
362	  if (!reason) return toast('请填写原因', 'warn');
363	  const p = pending; pending = null;
364	  document.getElementById('reasonModal').classList.remove('show');
365	  if (p) await postTransition(p.room, p.action, reason);
366	};
367	function closeReason() { pending = null; document.getElementById('reasonModal').classList.remove('show'); }
368	
369	async function postTransition(room, action, reason) {
370	  const idem = 'idem-' + Math.random().toString(36).slice(2, 10);
371	  try {
372	    const res = await fetch(`/api/rooms/${room.id}/transitions`, {
373	      method: 'POST',
374	      headers: { 'Content-Type': 'application/json', ...operator(), 'Idempotency-Key': idem },
375	      body: JSON.stringify({ action, expectedVersion: room.version, reason, idempotencyKey: idem }),
376	    });
377	    const body = await res.json();
378	    if (!res.ok) {
379	      if (body.code === 'VERSION_CONFLICT') {
380	        toast(`⛔ ${body.error}`, 'error');
381	        await fetchSnapshot();
382	      } else {
383	        toast(body.error || '操作失败', 'error');
384	      }
385	      return;
386	    }
387	    toast(body.duplicated ? '重复请求已幂等处理' : '操作成功', 'ok');
388	    await fetchSnapshot();
389	  } catch (e) {
390	    toast('网络错误：' + e.message, 'error');
391	  }
392	}
393	
394	async function showHistory(room) {
395	  document.getElementById('historyTitle').textContent = `${room.name} · 交接记录`;
396	  const res = await fetch(`/api/rooms/${room.id}/history?limit=100`);
397	  const data = await res.json();
398	  document.getElementById('historyBody').innerHTML = data.events.map(ev => `
399	    <tr>
400	      <td>${new Date(ev.at).toLocaleString('zh-CN', { hour12: false })}</td>
401	      <td>${ev.actionLabel}</td>
402	      <td>${ev.fromStateLabel ? ev.fromStateLabel + ' → ' : ''}${ev.toStateLabel}<br>
403	        <span style="color:var(--muted)">v${ev.version}</span></td>
404	      <td>${ev.operatorName}<br><span style="color:var(--muted)">${ev.operatorRoleLabel}</span></td>
405	      <td>${ev.toResponsible}</td>
406	      <td class="reason">${ev.reason ? escapeHtml(ev.reason) : '—'}</td>
407	    </tr>`).join('') || '<tr><td colspan="6" style="color:var(--muted)">暂无记录</td></tr>';
408	  document.getElementById('historyModal').classList.add('show');
409	}
410	
411	// ---- toast ----
412	function toast(msg, kind = '') {
413	  const el = document.createElement('div');
414	  el.className = `toast ${kind}`;
415	  el.textContent = msg;
416	  document.getElementById('toasts').appendChild(el);
417	  setTimeout(() => { el.style.opacity = '0'; el.style.transition = 'opacity .3s'; setTimeout(() => el.remove(), 300); }, 3600);
418	}
419	
420	// 倒计时每秒刷新（纯前端展示，不改变状态）
421	setInterval(() => {
422	  document.querySelectorAll('.timer[data-since]').forEach(el => {
423	    const since = el.dataset.since;
424	    if (since) el.textContent = fmtDur(elapsed(since));
425	  });
426	}, 1000);
427	
428	saveIdentity();
429	fetchSnapshot();
430	connectSSE();
431	</script>
432	</body>
433	</html>
