}

input.new_string:
_load() {
  const f = this._file();
  if (!fs.existsSync(f)) return;
  try {
    const data = JSON.parse(fs.readFileSync(f, 'utf8'));
    for (const r of data.rooms || []) {
      this.rooms.set(r.id, { ...r });
      this.events.set(r.id, []);
    }
    // 旧版本落盘的事件可能没有全局 seq：按发生时间确定总顺序后补号，
    // 之后新事件从 seqMax + 1 继续，保证全局限序在重启后不回退
    const loaded = (data.events || [])
      .filter((ev) => this.events.has(ev.roomId))
      .sort((a, b) => {
        const c = new Date(a.at) - new Date(b.at);
        if (c) return c;
        if (a.roomId !== b.roomId) return a.roomId < b.roomId ? -1 : 1;
        return a.version - b.version;
      });
    for (const ev of loaded) {
      if (!Number.isInteger(ev.seq)) ev.seq = ++this.seqMax;
      else this.seqMax = Math.max(this.seqMax, ev.seq);
      this.events.get(ev.roomId).push(ev);
    }
    // 按 seq 校正各包厢内事件顺序
    for (const evs of this.events.values()) {
      evs.sort((a, b) => a.seq - b.seq);
    }
    for (const [id] of this.rooms) this._rebuildRoomFromEvents(id, { touch: false });
    for (const [k, v] of Object.entries(data.alerts || {})) this.alerts.set(k, { ...v });
  } catch (e) {
    console.error('加载数据失败，使用空数据启动:', e.message);
  }
}

