  loaded.sort((a, b) => {
    const c = new Date(a.at) - new Date(b.at);
    if (c) return c;
    if (a.roomId !== b.roomId) return a.roomId < b.roomId ? -1 : 1;
    return a.version - b.version;
  });
  for (const ev of loaded) ev.seq = ++this.seqMax;
} else {
  this.seqMax = loaded.reduce((m, ev) => Math.max(m, ev.seq), 0);
}
for (const ev of loaded) this.events.get(ev.roomId).push(ev);
// 按 seq 校正各包厢内事件顺序
for (const evs of this.events.values()) {
  evs.sort((a, b) => a.seq - b.seq);
}

