history(roomId, limit = 50) {
  const room = this.rooms.get(roomId);
  if (!room) throw new DomainError('包厢不存在', 404, 'NOT_FOUND');
  const evs = this.events.get(roomId) || [];
  return evs.slice(-limit).reverse();
}

/**
 * 交接动态（跨包厢全局事件流），按 seq 升序返回
 * @param {object} q
 *   afterSeq: 只返回 seq 严格大于该值的事件（断线补齐游标，不传则取最近 limit 条）
 *   limit: 最多返回条数
 * 返回 { events, latestSeq, hasMore, nextCursor }，分页时“更早的页在前”
 */
feed({ afterSeq = null, limit = 50 } = {}) {
  const all = [];
  for (const evs of this.events.values()) {
    for (const ev of evs) all.push(ev);
  }
  all.sort((a, b) => a.seq - b.seq);
  const latestSeq = this.seqMax;
  if (afterSeq == null) {
    return { events: all.slice(-limit), latestSeq, hasMore: false, nextCursor: null };
  }
  const seq = Number(afterSeq);
  if (!Number.isFinite(seq)) throw new DomainError('afterSeq 参数无效');
  const newer = all.filter((ev) => ev.seq > seq);
  const page = newer.slice(-limit);
  const hasMore = newer.length > page.length;
  return {
    events: page,
    latestSeq,
    hasMore,
    // 本页最早一条的前一个 seq：先拿更早的页，顺序天然是发生顺序
    nextCursor: hasMore && page.length ? page[0].seq - 1 : null,
  };
}

