let state = null;
const FEED_KEEP = 100;   // 本栏最多保留条数
const FEED_PAGE = 50;    // 首屏与每次补齐的条数
const feedItems = [];    // 按 seq 倒序（最新在前）
const seenSeqs = new Set();
let lastSeq = 0;         // 已并入本栏的最大 seq（断线补齐游标）
let everConnected = false;

// 合并动态：同一 seq 只出现一次，统一按发生顺序（seq）排列
function mergeFeedEvents(events) {
  let added = 0;
  for (const ev of events || []) {
    if (!ev || !Number.isInteger(ev.seq) || seenSeqs.has(ev.seq)) continue;
    seenSeqs.add(ev.seq);
    feedItems.push(ev);
    added++;
  }
  if (added) {
    feedItems.sort((a, b) => b.seq - a.seq);
    for (const ev of feedItems.splice(FEED_KEEP)) seenSeqs.delete(ev.seq);
    lastSeq = Math.max(lastSeq, feedItems[0]?.seq || 0);
    if (state) renderFeed();
  }
}

// 首屏：先带出最近一段动态，再继续实时追加
async function loadInitialFeed() {
  try {
    const data = await fetchFeed(null);
    mergeFeedEvents(data.events);
  } catch (e) { /* 拉取失败不影响实时推送，重连时还会补齐 */ }
}

// 重连/换设备：从最后收到的 seq 起，按发生顺序翻页补齐断线期间的全部变更
async function catchUpFeed() {
  try {
    let cursor = lastSeq;
    for (let guard = 0; guard < 20; guard++) {
      const data = await fetchFeed(cursor);
      // nextCursor 指向更早一页；先进来的旧页与后进来的新页统一由 merge 排序
      mergeFeedEvents(data.events);
      cursor = data.nextCursor;
      if (!data.hasMore || cursor == null) break;
    }
  } catch (e) { /* 网络仍不可用，下次重连继续补 */ }
}

async function fetchFeed(afterSeq) {
  const q = new URLSearchParams({ limit: FEED_PAGE });
  if (afterSeq != null) q.set('afterSeq', afterSeq);
  const res = await fetch(`/api/feed?${q}`);
  if (!res.ok) throw new Error('feed fetch failed');
  return res.json();
}

