async function fetchSnapshot() {
  const res = await fetch('/api/rooms');
  state = await res.json();
  render();
}

function connectSSE() {
  const es = new EventSource('/api/events');
  es.addEventListener('hello', () => {
    setConn(true);
    // 第一次连上由首屏逻辑加载；之后每次（断线重连）按 seq 补齐缺口
    if (everConnected) catchUpFeed();
    else { everConnected = true; loadInitialFeed(); }
    fetchSnapshot();
  });
  es.addEventListener('transition', (e) => {
    const { event, room } = JSON.parse(e.data);
