import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';

function tmpDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ktv-server-'));
}

function startServer(dir) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [path.join(import.meta.dirname, '..', 'src', 'server.js')], {
      env: { ...process.env, PORT: '0', DATA_DIR: dir },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let buf = '';
    const onData = (chunk) => {
      buf += chunk;
      const m = buf.match(/http:\/\/localhost:(\d+)/);
      if (m) {
        child.stdout.off('data', onData);
        child.stderr.off('data', onErr);
        resolve({ child, base: `http://localhost:${m[1]}` });
      }
    };
    const onErr = (chunk) => { reject(new Error(chunk.toString())); };
    child.stdout.on('data', onData);
    child.stderr.on('data', onErr);
    child.on('error', reject);
  });
}

const FRONT_HEADERS = {
  'X-Role': 'FRONT',
  'X-User-Id': 'u-front',
  'X-User-Name': '前台-小林',
};
const MANAGER_HEADERS = {
  'X-Role': 'MANAGER',
  'X-User-Id': 'u-mgr',
  'X-User-Name': '值班经理-老赵',
};

async function postTransition(base, roomId, body, headers) {
  const res = await fetch(`${base}/api/rooms/${roomId}/transitions`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...headers },
    body: JSON.stringify(body),
  });
  const data = await res.json();
  assert.ok(res.ok, data.error);
  return data;
}

