    // 把 R303（待清洁 v1）推进：保洁接单 → 报检 → 经理驳回（填原因）
    const rooms = await (await fetch(`${base}/api/rooms`)).json();
    const r303 = rooms.rooms.find((r) => r.id === 'R303');
    assert.equal(r303.version, 1);

    const claim = await postTransition(base, 'R303', {
      action: 'CLAIM', expectedVersion: 1,
    }, { 'X-Role': 'CLEANER', 'X-User-Id': 'u-c1', 'X-User-Name': L('保洁-王姐') });
    const submit = await postTransition(base, 'R303', {
      action: 'SUBMIT_CLEAN', expectedVersion: 2,
    }, { 'X-Role': 'CLEANER', 'X-User-Id': 'u-c1', 'X-User-Name': L('保洁-王姐') });
    const reject = await postTransition(base, 'R303', {
      action: 'REJECT_INSPECTION', expectedVersion: 3, reason: '卫生间水渍未擦干',
    }, MANAGER_HEADERS);

    // 同一幂等键重试：不新增事件
    await postTransition(base, 'R303', {
      action: 'REJECT_INSPECTION', expectedVersion: 99, reason: '卫生间水渍未擦干',
      idempotencyKey: reject.event.idempotencyKey,
    }, MANAGER_HEADERS);

    // 看板在 seq=8（播种最后一条）时断线：重连只拿到 9/10/11，顺序即发生顺序
    const gap = await (await fetch(`${base}/api/feed?afterSeq=8&limit=50`)).json();
    assert.deepEqual(gap.events.map((e) => e.seq), [9, 10, 11]);
    assert.deepEqual(gap.events.map((e) => e.action), ['CLAIM', 'SUBMIT_CLEAN', 'REJECT_INSPECTION']);
    assert.equal(gap.events.at(-1).reason, '卫生间水渍未擦干');
    assert.equal(gap.latestSeq, reject.event.seq);
    assert.equal(gap.hasMore, false);

    // 全量动态中同一笔变更只有一条
    const all = await (await fetch(`${base}/api/feed?limit=50`)).json();
    assert.equal(all.events.length, 11);
    assert.equal(all.events.filter((e) => e.seq === reject.event.seq).length, 1);
    assert.equal(new Set(all.events.map((e) => e.seq)).size, all.events.length);
  } finally {
    child.kill();
  }
});

test('分页：缺口超过一页时从最早页开始，hasMore/nextCursor 可遍历全部', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    const rooms = await (await fetch(`${base}/api/rooms`)).json();
    const r303 = rooms.rooms.find((r) => r.id === 'R303');
    await postTransition(base, 'R303', { action: 'CLAIM', expectedVersion: r303.version }, {
      'X-Role': 'CLEANER', 'X-User-Id': 'u-c1', 'X-User-Name': L('保洁-王姐'),
    });

    // afterSeq=0、每页 3 条：从最早一页（1,2,3）开始
    let data = await (await fetch(`${base}/api/feed?afterSeq=0&limit=3`)).json();
    assert.deepEqual(data.events.map((e) => e.seq), [1, 2, 3]);
    assert.equal(data.hasMore, true);
    assert.equal(data.nextCursor, 3);

    // 翻到最后一页
    data = await (await fetch(`${base}/api/feed?afterSeq=${data.nextCursor}&limit=3`)).json();
    assert.deepEqual(data.events.map((e) => e.seq), [4, 5, 6]);
    assert.equal(data.nextCursor, 6);
    data = await (await fetch(`${base}/api/feed?afterSeq=${data.nextCursor}&limit=3`)).json();
    assert.deepEqual(data.events.map((e) => e.seq), [7, 8, 9]);
    assert.equal(data.hasMore, false);
    assert.equal(data.nextCursor, null);

    // 非法游标 400
    const bad = await fetch(`${base}/api/feed?afterSeq=abc`);
    assert.equal(bad.status, 400);

    // 已追平后重连：空缺口
    const empty = await (await fetch(`${base}/api/feed?afterSeq=${data.latestSeq}&limit=3`)).json();
    assert.deepEqual(empty.events, []);
    assert.equal(empty.hasMore, false);
  } finally {
    child.kill();
  }
});

