nameEl.value = localStorage.getItem('userName') || PRESET_NAME[roleEl.value];
roleEl.onchange = () => { nameEl.value = PRESET_NAME[roleEl.value]; saveIdentity(); render(); };
nameEl.onchange = saveIdentity;
