test('limit 传 0 / 负数 / 非数字：回退默认 50，不返回全量', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    // 先让 R303 走完一段流转，使 R303 的交接记录达到 5 条
    const cleaner = { 'X-Role': 'CLEANER', 'X-User-Id': 'u-c1', 'X-User-Name': L('保洁-王姐') };
    const flow = [
      ['CLAIM', 1], ['SUBMIT_CLEAN', 2],
    ];
    for (const [action, v] of flow) await postTransition(base, 'R303', { action, expectedVersion: v }, cleaner);
    await postTransition(base, 'R303', {
      action: 'REJECT_INSPECTION', expectedVersion: 3, reason: '地面有污渍',
    }, MANAGER_HEADERS);
    await postTransition(base, 'R303', { action: 'SUBMIT_CLEAN', expectedVersion: 4 }, cleaner);

    // R303 共 5 条包厢交接记录（含播种 1 条）
    const good = await (await fetch(`${base}/api/rooms/R303/history?limit=2`)).json();
    assert.equal(good.events.length, 2);

    for (const bad of ['0', '-3', 'abc', '1.5', '', ' ']) {
      const qs = bad === '' ? 'limit=' : `limit=${encodeURIComponent(bad)}`;
      const d = await (await fetch(`${base}/api/rooms/R303/history?${qs}`)).json();
      assert.ok(d.events.length <= 50, `history limit=${JSON.stringify(bad)} 不应回成全量`);
    }
    // 0 与非数字时取默认 50：房间只有 5 条，所以仍是 5 条（而不是按字面 0 条/报错）
    for (const bad of ['0', 'abc']) {
      const d = await (await fetch(`${base}/api/rooms/R303/history?limit=${bad}`)).json();
      assert.equal(d.events.length, 5);
    }

    // /api/feed 同样：播种 8 条 + 新增 4 条 = 12 条；limit=0 必须回退默认而非返回 0 条
    const zero = await (await fetch(`${base}/api/feed?limit=0`)).json();
    assert.equal(zero.events.length, 12);
    const nan = await (await fetch(`${base}/api/feed?limit=abc`)).json();
    assert.equal(nan.events.length, 12);
    const neg = await (await fetch(`${base}/api/feed?limit=-1`)).json();
    assert.equal(neg.events.length, 12);
    // 正常小 limit 仍然生效
    assert.equal((await (await fetch(`${base}/api/feed?limit=3`)).json()).events.length, 3);
  } finally {
    child.kill();
  }
});

test('中文姓名身份（percent-encoded 头）可正常流转，事件里存解码后的中文 id/name', async () => {
  const { child, base } = await startServer(tmpDir());
  try {
    // 模拟看板前端 operator()：整段 id（含冒号）与姓名都 encodeURIComponent
    const cnCleaner = {
      'X-Role': 'CLEANER',
      'X-User-Id': L('CLEANER:保洁-王姐'),
      'X-User-Name': L('保洁-王姐'),
    };
    const r = await postTransition(base, 'R303', { action: 'CLAIM', expectedVersion: 1 }, cnCleaner);
    assert.equal(r.ok, true);
    assert.equal(r.duplicated, false);
    assert.equal(r.event.operatorName, '保洁-王姐');
    assert.equal(r.event.operatorId, 'CLEANER:保洁-王姐');
    assert.equal(r.event.toResponsible, '保洁-王姐');

    // 同一身份继续流转 + 放弃自己接的单（RELEASE_CLAIM 按 operatorId 判本人），应放行
    await postTransition(base, 'R303', { action: 'RELEASE_CLAIM', expectedVersion: 2 }, cnCleaner);
    const rooms = await (await fetch(`${base}/api/rooms`)).json();
